// Weekly scorecard. Answers the question the log exists to answer: is the volume there,
// and is any of it warm? Sent even when the week was empty, because an empty week is the
// single most useful thing this can tell you.
const apps = items.map(i => i.json);
const now = Date.now();
const DAY = 86400000;

const age = a => (now - new Date(a.applied_date).getTime()) / DAY;
const thisWeek = apps.filter(a => a.applied_date && age(a) <= 7);

const warm = a => /referral|network|friend|colleague/i.test(a.source || '');
const referrals = thisWeek.filter(warm).length;

const quiet = apps.filter(a => a.status === 'applied' && a.applied_date && age(a) >= 14).length;
const replied = apps.filter(a => a.status !== 'applied' && a.status !== 'saved').length;
const rate = apps.length ? ((replied / apps.length) * 100).toFixed(1) : '0.0';

const bySource = {};
for (const a of thisWeek) bySource[a.source || '—'] = (bySource[a.source || '—'] || 0) + 1;
const sources = Object.entries(bySource)
  .sort((a, b) => b[1] - a[1])
  .map(([s, n]) => `${s} ${n}`)
  .join(' · ') || 'none';

const verdict =
  thisWeek.length === 0 ? '**No applications this week.**'
  : thisWeek.length < 10 ? `**${thisWeek.length} this week** — cold applications need ~25/week to produce interviews.`
  : `**${thisWeek.length} this week** — that is the right volume.`;

const referralNote =
  referrals === 0 ? '**0 referrals.** Cold converts at 2–5%, referred at 20–50%. This is the gap.'
  : `${referrals} referral${referrals > 1 ? 's' : ''} this week.`;

const content = [
  '**Weekly scorecard**',
  verdict,
  referralNote,
  `Sources: ${sources}`,
  `Total tracked: ${apps.length} · replied: ${replied} (${rate}%) · silent 14d+: ${quiet}`,
].join('\n');

return [{ json: { content } }];
